from lark import Lark, Transformer, v_args

# --- Lark Grammar and Parser ---

ICON_GRAMMAR = r"""
    ?start: icon

    icon : "{" [coordinate_system] "," graphics "}"

    coordinate_system : SIGNED_NUMBER "," SIGNED_NUMBER "," SIGNED_NUMBER "," SIGNED_NUMBER "," boolean "," [SIGNED_NUMBER] "," [grid]
    grid : point

    graphics : "{" [graphic_item ("," graphic_item)*] "}"

    graphic_item : rectangle | line | text

    rectangle : "Rectangle(" boolean "," point "," SIGNED_NUMBER "," color "," color "," line_pattern "," fill_pattern "," SIGNED_NUMBER "," border_pattern "," extent "," SIGNED_NUMBER ")"
    line : "Line(" boolean "," point "," SIGNED_NUMBER "," points "," color "," line_pattern "," SIGNED_NUMBER "," arrow_pair "," SIGNED_NUMBER "," smooth ")"
    text : "Text(" boolean "," point "," SIGNED_NUMBER "," extent "," ESCAPED_STRING "," SIGNED_NUMBER "," ESCAPED_STRING "," text_style_list "," color "," text_alignment "," SIGNED_NUMBER ")"

    points : "{" [point ("," point)*] "}"
    extent : "{" point "," point "}"
    point : "{" SIGNED_NUMBER "," SIGNED_NUMBER "}"
    color : "{" SIGNED_NUMBER "," SIGNED_NUMBER "," SIGNED_NUMBER "}"
    arrow_pair : "{" arrow "," arrow "}"
    text_style_list : "{" [text_style ("," text_style)*] "}"

    boolean : "true" -> true | "false" -> false
    line_pattern : "LinePattern." WORD -> line_pattern
    fill_pattern : "FillPattern." WORD -> fill_pattern
    border_pattern : "BorderPattern." WORD -> border_pattern
    smooth : "Smooth." WORD -> smooth
    arrow : "Arrow." WORD -> arrow
    text_style : "TextStyle." WORD -> text_style
    text_alignment : "TextAlignment." WORD -> text_alignment

    %import common.WORD
    %import common.SIGNED_NUMBER
    %import common.ESCAPED_STRING
    %import common.WS
    %ignore WS
"""


@v_args(inline=True)
class IconTransformer(Transformer):
    """Transforms the Lark parse tree into annotation dataclasses."""

    def icon(self, coord_sys, graphics):
        return Icon(coordinate_system=coord_sys, graphics=graphics)

    def coordinate_system(self, x1, y1, x2, y2, preserve_aspect, initial_scale=0.1, grid=(1.0, 1.0)):
        return CoordinateSystem(
            extent=((x1, y1), (x2, y2)),
            preserve_aspect_ratio=preserve_aspect,
            initial_scale=initial_scale or 0.1,
            grid=grid or (1.0, 1.0),
        )

    def graphics(self, *items):
        return list(items)

    def rectangle(self, visible, origin, rotation, line_color, fill_color, pattern, fill_pattern, line_thickness, border_pattern, extent, radius):
        return Rectangle(
            graphic_item=GraphicItem(visible=visible, origin=origin, rotation=rotation),
            filled_shape=FilledShape(
                line_color=line_color,
                fill_color=fill_color,
                pattern=pattern,
                fill_pattern=fill_pattern,
                line_thickness=line_thickness,
            ),
            border_pattern=border_pattern,
            extent=extent,
            radius=radius,
        )

    def line(self, visible, origin, rotation, points, color, pattern, thickness, arrow, arrow_size, smooth):
        return Line(
            graphic_item=GraphicItem(visible=visible, origin=origin, rotation=rotation),
            points=points,
            color=color,
            pattern=pattern,
            thickness=thickness,
            arrow=arrow,
            arrow_size=arrow_size,
            smooth=smooth,
        )

    def text(self, visible, origin, rotation, extent, string, font_size, font_name, text_style, text_color, horizontal_alignment, index):
        return Text(
            graphic_item=GraphicItem(visible=visible, origin=origin, rotation=rotation),
            extent=extent,
            string=string,
            font_size=font_size,
            font_name=font_name,
            text_style=text_style,
            text_color=text_color,
            horizontal_alignment=horizontal_alignment,
            index=index,
        )

    def points(self, *points):
        return list(points)

    def extent(self, p1, p2):
        return (p1, p2)

    def point(self, x, y):
        return (float(x), float(y))

    def color(self, r, g, b):
        return (int(r), int(g), int(b))

    def arrow_pair(self, a1, a2):
        return (a1, a2)

    def text_style_list(self, *styles):
        return list(styles)

    def line_pattern(self, value):
        return LinePattern(value.value)

    def fill_pattern(self, value):
        return FillPattern(value.value)

    def border_pattern(self, value):
        return BorderPattern(value.value)

    def smooth(self, value):
        return Smooth(value.value)

    def arrow(self, value):
        return Arrow(value.value)

    def text_style(self, value):
        return TextStyle(value.value)

    def text_alignment(self, value):
        return TextAlignment(value.value)

    def true(self, _):
        return True

    def false(self, _):
        return False

    def SIGNED_NUMBER(self, n):
        return float(n)

